<template>
	<d2-container>
		<template slot="header">
			<div class="radio">
				更新日期排序：
				<el-radio-group v-model="reverse">
					<el-radio :label="true">倒序</el-radio>
					<el-radio :label="false">正序</el-radio>
				</el-radio-group>
			</div>
		</template>


		<el-timeline :reverse="reverse">
			<el-timeline-item v-for="(item, index) in activities" :key="index" :timestamp="item.CreateTime" placement="top" color="#409EFF">
				<el-card>
					<h2> {{item.Title}} </h2>
					<p>{{item.Content}}</p>
				</el-card>

			</el-timeline-item>
		</el-timeline>
	</d2-container>
</template>

<script>
	import {
		GetAllUpdateLog
	} from '@api/UpdateLog.js'
	export default {
		name: 'UpdateLog',
		data() {
			return {
				reverse: true,
				activities: []
			}
		},
		mounted() {
			this.getAllUpdateLog()
		},
		methods: {
			getAllUpdateLog() {
				GetAllUpdateLog()
					.then(res => {
						this.activities =(res.list)

					})
					.catch(err => {})
			},

		}


	}
</script>

